CREATE TABLE public.tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tenants TO authenticated; GRANT ALL ON public.tenants TO service_role;
ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.tenant_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),user_id uuid NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','invited','inactive')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id));
GRANT SELECT ON public.tenant_memberships TO authenticated; GRANT ALL ON public.tenant_memberships TO service_role;
ALTER TABLE public.tenant_memberships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.tenant_settings(tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id),logo_url text,primary_color text NOT NULL DEFAULT '#1B4332' CHECK(primary_color ~ '^#[0-9A-Fa-f]{6}$'),address text NOT NULL DEFAULT '',contact jsonb NOT NULL DEFAULT '{}'::jsonb,bank jsonb NOT NULL DEFAULT '{}'::jsonb,ppn_rate numeric NOT NULL DEFAULT 0 CHECK(ppn_rate BETWEEN 0 AND 100),discount_approval_threshold_pct numeric NOT NULL DEFAULT 0 CHECK(discount_approval_threshold_pct BETWEEN 0 AND 100),doc_numbering jsonb NOT NULL DEFAULT '{"invoice":"INV/{CLIENT}/{YYYY}/{MM}/{SEQ}"}'::jsonb,currency text NOT NULL DEFAULT 'IDR' CHECK(currency='IDR'));
GRANT SELECT,UPDATE ON public.tenant_settings TO authenticated; GRANT ALL ON public.tenant_settings TO service_role;
ALTER TABLE public.tenant_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.platform_admins(user_id uuid PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_admins TO authenticated; GRANT ALL ON public.platform_admins TO service_role;
ALTER TABLE public.platform_admins ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_own ON public.platform_admins FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.approval_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),type text NOT NULL CHECK(type IN ('delete','discount','cancel')),entity_type text NOT NULL,entity_id uuid NOT NULL,requested_by uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by uuid,decided_at timestamptz,reason text NOT NULL CHECK(length(btrim(reason))>0),decision_reason text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.approval_requests TO authenticated; GRANT ALL ON public.approval_requests TO service_role;
ALTER TABLE public.approval_requests ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX approval_pending_unique ON public.approval_requests(tenant_id,type,entity_type,entity_id) WHERE status='pending';
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),actor_id uuid,action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,diff jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.document_counters(tenant_id uuid NOT NULL REFERENCES public.tenants(id),client_code text NOT NULL,document_type text NOT NULL,sequence bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,client_code,document_type));
GRANT SELECT ON public.document_counters TO authenticated; GRANT ALL ON public.document_counters TO service_role;
ALTER TABLE public.document_counters ENABLE ROW LEVEL SECURITY;
INSERT INTO public.tenants(slug,name) SELECT 'sedyain','Sedyain Indonesia' WHERE NOT EXISTS(SELECT 1 FROM public.tenants WHERE slug='sedyain');
INSERT INTO public.tenant_settings(tenant_id,logo_url,address,contact,bank) SELECT id,'/__l5e/assets-v1/44cb1f11-0d81-4a9a-a585-a43068c93a3d/sedyain_logo.png','Jl. Kebalen V No.32, RT.5/RW.5, Rw. Bar., Kec. Kby. Baru, Jakarta Selatan 12180','{"wa":"0817 001 9339","ig":"@sedyain.id","email":"admin@sedyain.id"}'::jsonb,'{"name":"BCA","account":"2109339339","holder":"SEDYAIN BERHASIL BERSAMA PT"}'::jsonb FROM public.tenants WHERE slug='sedyain';
INSERT INTO public.tenant_memberships(tenant_id,user_id) SELECT t.id,p.id FROM public.tenants t CROSS JOIN public.profiles p WHERE t.slug='sedyain';
DO $block$ DECLARE tbl text; tid uuid; BEGIN SELECT id INTO tid FROM public.tenants WHERE slug='sedyain'; FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members','user_roles','module_access'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN tenant_id uuid',tbl); EXECUTE format('UPDATE public.%I SET tenant_id=$1 WHERE tenant_id IS NULL',tbl) USING tid; EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY(tenant_id) REFERENCES public.tenants(id)',tbl,tbl||'_tenant_fk'); EXECUTE format('CREATE INDEX %I ON public.%I(tenant_id)',tbl||'_tenant_idx',tbl); END LOOP; FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN deleted_at timestamptz, ADD COLUMN deleted_by uuid, ADD COLUMN delete_reason text',tbl); EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I UNIQUE(tenant_id,id)',tbl,tbl||'_tenant_id_unique'); END LOOP; END $block$;
ALTER TABLE public.user_roles DROP CONSTRAINT user_roles_user_id_role_key; ALTER TABLE public.user_roles ADD CONSTRAINT user_roles_tenant_user_role UNIQUE(tenant_id,user_id,role);
ALTER TABLE public.module_access DROP CONSTRAINT module_access_user_id_module_key; ALTER TABLE public.module_access ADD CONSTRAINT module_access_tenant_user_module UNIQUE(tenant_id,user_id,module);
ALTER TABLE public.order_items ADD CONSTRAINT order_items_tenant_order_fk FOREIGN KEY(tenant_id,order_id) REFERENCES public.orders(tenant_id,id);
ALTER TABLE public.shipments ADD CONSTRAINT shipments_tenant_order_fk FOREIGN KEY(tenant_id,order_id) REFERENCES public.orders(tenant_id,id);
ALTER TABLE public.orders ADD CONSTRAINT orders_tenant_client_fk FOREIGN KEY(tenant_id,client_id) REFERENCES public.clients(tenant_id,id);
CREATE UNIQUE INDEX orders_tenant_invoice_unique ON public.orders(tenant_id,invoice_number) WHERE invoice_number IS NOT NULL AND btrim(invoice_number)<>'';
ALTER TABLE public.orders ADD COLUMN discount_pct numeric NOT NULL DEFAULT 0 CHECK(discount_pct BETWEEN 0 AND 100),ADD COLUMN document_status text NOT NULL DEFAULT 'final' CHECK(document_status IN ('draft','final','cancelled'));
DO $block$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['payables','receivables','cash_requests','expenses'] LOOP EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I CHECK(amount>=0 AND amount<>''NaN''::numeric)',tbl,tbl||'_valid_amount'); END LOOP; END $block$;
ALTER TABLE public.order_items ADD CONSTRAINT order_items_valid_numbers CHECK(qty>0 AND qty<>'NaN'::numeric AND price>=0 AND price<>'NaN'::numeric);
ALTER TABLE public.pricelist_items ADD CONSTRAINT pricelist_valid_price CHECK(price>=0 AND price<>'NaN'::numeric);
ALTER TABLE public.clients ADD CONSTRAINT clients_valid_status CHECK(status IN ('Lead Baru','Follow Up','Negosiasi','Deal','Tidak Lanjut'));
ALTER TABLE public.payables ADD CONSTRAINT payables_valid_status CHECK(status IN ('Belum Bayar','Sudah Bayar'));
ALTER TABLE public.receivables ADD CONSTRAINT receivables_valid_status CHECK(status IN ('Belum Tertagih','Lunas'));
ALTER TABLE public.cash_requests ADD CONSTRAINT cash_valid_status CHECK(status IN ('Pending','Disetujui','Ditransfer','Ditolak'));
ALTER TABLE public.expenses ADD CONSTRAINT expenses_valid_status CHECK(status IN ('Draft','Disetujui','Dibayar'));
ALTER TABLE public.tasks ADD CONSTRAINT tasks_valid_status CHECK(status IN ('To Do','In Progress','Review','Done'));
ALTER TABLE public.shipments ADD CONSTRAINT shipments_valid_status CHECK(status IN ('Menunggu','Dikemas','Dalam Perjalanan','Terkirim'));